MOD = 998244353

import math

def powmod(x, n, p):
    result = 1
    temp = x % p
    while n > 0:
        if n % 2 == 1:
            result = (result * temp) % p
        temp = (temp ** 2) % p
        n //= 2
    return result

def distinct_arrays():
    N, Q = map(int, input().split())
    bit_counts = [0] * N
    possible_xor_values = [0] * N + [True] * (N + 1)

    for _ in range(Q):
        l, r = map(int, input().split())
        for i in range(l - 1, r):
            bit_counts[i] ^= 1
            if possible_xor_values[i] ** 2 == possible_xor_values[i]:
                possible_xor_values[i + 1] = True
            possible_xor_values[i + 1] ^= possible_xor_values[i]
        for i in range(l - 1, r):
            possible_xor_values[i] = False

    result = 1
    for i, count in enumerate(bit_counts):
        if count:
            result *= powmod(2, N - i, MOD - 1)
            result %= MOD
    return result

